import React from 'react';
import { useApp } from '../context/AppContext';
import { getTheme } from '../utils/theme';
import StatCard from '../components/common/StatCard';

const QUICK_ACTIONS = {
  student: [
    { label: 'Browse Colleges', icon: '🏫', page: 'colleges' },
    { label: 'View Resources', icon: '📚', page: 'resources' },
    { label: 'Study Routine', icon: '✅', page: 'routine' },
  ],
  teacher: [
    { label: 'Upload Resource', icon: '📤', page: 'upload' },
    { label: 'Browse Resources', icon: '📚', page: 'resources' },
    { label: 'View Colleges', icon: '🏫', page: 'colleges' },
  ],
  admin: [
    { label: 'Manage Users', icon: '👥', page: 'admin' },
    { label: 'All Resources', icon: '📚', page: 'resources' },
    { label: 'View Colleges', icon: '🏫', page: 'colleges' },
  ],
};

export default function Dashboard() {
  const { user, resources, setPage, dark } = useApp();
  const css = getTheme(dark);

  const hour = new Date().getHours();
  const greeting =
    hour < 12 ? 'Good morning' : hour < 17 ? 'Good afternoon' : 'Good evening';

  const statsMap = {
    student: [
      { label: 'Resources Accessed', value: '47', icon: '📚', color: '#6366f1' },
      { label: 'Colleges Explored', value: '3', icon: '🏫', color: '#10b981' },
      { label: 'Tasks Done Today', value: '4/7', icon: '✅', color: '#f59e0b' },
      { label: 'Sessions Booked', value: '2', icon: '🙋', color: '#ef4444' },
    ],
    teacher: [
      {
        label: 'Your Uploads',
        value: String(resources.filter((r) => r.uploadedBy === user?.name).length),
        icon: '📤',
        color: '#6366f1',
      },
      { label: 'Total Downloads', value: '2.4K', icon: '⬇️', color: '#10b981' },
      { label: 'Sessions Scheduled', value: '6', icon: '📅', color: '#f59e0b' },
      { label: 'Students Reached', value: '840', icon: '👥', color: '#ef4444' },
    ],
    admin: [
      { label: 'Total Users', value: '24,381', icon: '👥', color: '#6366f1' },
      { label: 'Resources', value: String(resources.length), icon: '📚', color: '#10b981' },
      { label: 'Colleges', value: '6', icon: '🏫', color: '#f59e0b' },
      { label: 'Sessions Today', value: '12', icon: '📅', color: '#ef4444' },
    ],
  };

  const stats = statsMap[user?.role] || statsMap.student;
  const actions = QUICK_ACTIONS[user?.role] || QUICK_ACTIONS.student;
  const recent = resources.slice(0, 5);

  const typeIcon = { note: '📄', paper: '📝', video: '🎬', doubt: '🙋' };

  return (
    <div className="fade-in">
      {/* Page header */}
      <div style={{ marginBottom: 32 }}>
        <h1
          style={{
            fontSize: 28,
            fontWeight: 800,
            letterSpacing: '-1px',
            color: dark ? '#fff' : '#0f0f23',
            marginBottom: 6,
          }}
        >
          {greeting}, {user?.name.split(' ')[0]} 👋
        </h1>
        <p style={{ color: dark ? '#64748b' : '#94a3b8', fontSize: 15 }}>
          {user?.role === 'student'
            ? 'Track your progress and explore study materials.'
            : user?.role === 'teacher'
            ? 'Manage uploads, sessions, and track your impact.'
            : 'Full platform overview — users, content, and analytics.'}
        </p>
      </div>

      {/* Stats grid */}
      <div
        className="stagger"
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit,minmax(200px,1fr))',
          gap: 16,
          marginBottom: 32,
        }}
      >
        {stats.map((s, i) => (
          <StatCard key={i} {...s} />
        ))}
      </div>

      {/* Content grid */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: '1.6fr 1fr',
          gap: 20,
          marginBottom: 32,
        }}
      >
        {/* Recent resources */}
        <div style={{ ...css.card, padding: 24, borderRadius: 18 }}>
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              marginBottom: 18,
            }}
          >
            <h3
              style={{
                fontSize: 16,
                fontWeight: 700,
                color: dark ? '#f1f5f9' : '#0f0f23',
              }}
            >
              Recent Resources
            </h3>
            <button
              onClick={() => setPage('resources')}
              style={{
                background: 'none',
                border: 'none',
                color: '#818cf8',
                cursor: 'pointer',
                fontSize: 13,
                fontWeight: 600,
                fontFamily: 'inherit',
              }}
            >
              View all →
            </button>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            {recent.map((r) => (
              <div
                key={r.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 12,
                  padding: '10px 12px',
                  borderRadius: 10,
                  background: dark ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.025)',
                  cursor: 'pointer',
                  transition: 'background 0.15s',
                }}
                onMouseEnter={(e) =>
                  (e.currentTarget.style.background = dark
                    ? 'rgba(255,255,255,0.06)'
                    : 'rgba(0,0,0,0.05)')
                }
                onMouseLeave={(e) =>
                  (e.currentTarget.style.background = dark
                    ? 'rgba(255,255,255,0.03)'
                    : 'rgba(0,0,0,0.025)')
                }
              >
                <div
                  style={{
                    width: 38,
                    height: 38,
                    borderRadius: 10,
                    background: 'rgba(99,102,241,0.15)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: 18,
                    flexShrink: 0,
                  }}
                >
                  {typeIcon[r.type]}
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <p
                    style={{
                      fontSize: 13,
                      fontWeight: 600,
                      color: dark ? '#f1f5f9' : '#0f0f23',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                    }}
                  >
                    {r.title}
                  </p>
                  <p style={{ fontSize: 11, color: dark ? '#475569' : '#94a3b8', marginTop: 2 }}>
                    {r.subject} · {r.uploadedBy} · {r.date}
                  </p>
                </div>
                <span
                  style={{
                    fontSize: 11,
                    padding: '2px 8px',
                    borderRadius: 6,
                    background: 'rgba(99,102,241,0.15)',
                    color: '#818cf8',
                    fontWeight: 600,
                    textTransform: 'capitalize',
                    flexShrink: 0,
                  }}
                >
                  {r.type}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Quick actions */}
        <div style={{ ...css.card, padding: 24, borderRadius: 18 }}>
          <h3
            style={{
              fontSize: 16,
              fontWeight: 700,
              color: dark ? '#f1f5f9' : '#0f0f23',
              marginBottom: 18,
            }}
          >
            Quick Actions
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            {actions.map((a) => (
              <button
                key={a.page}
                onClick={() => setPage(a.page)}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 12,
                  padding: '14px 16px',
                  borderRadius: 12,
                  border: `1px solid ${dark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)'}`,
                  background: 'transparent',
                  color: dark ? '#f1f5f9' : '#0f0f23',
                  fontSize: 14,
                  fontWeight: 500,
                  cursor: 'pointer',
                  textAlign: 'left',
                  width: '100%',
                  transition: 'all 0.15s',
                  fontFamily: 'inherit',
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.borderColor = '#6366f1';
                  e.currentTarget.style.background = 'rgba(99,102,241,0.06)';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.borderColor = dark
                    ? 'rgba(255,255,255,0.06)'
                    : 'rgba(0,0,0,0.06)';
                  e.currentTarget.style.background = 'transparent';
                }}
              >
                <span style={{ fontSize: 20 }}>{a.icon}</span>
                <span style={{ flex: 1 }}>{a.label}</span>
                <span style={{ color: dark ? '#475569' : '#94a3b8', fontSize: 16 }}>→</span>
              </button>
            ))}
          </div>

          {/* Role badge */}
          <div
            style={{
              marginTop: 20,
              padding: '14px 16px',
              borderRadius: 12,
              background:
                user?.role === 'student'
                  ? 'rgba(99,102,241,0.1)'
                  : user?.role === 'teacher'
                  ? 'rgba(16,185,129,0.1)'
                  : 'rgba(245,158,11,0.1)',
              border: `1px solid ${
                user?.role === 'student'
                  ? 'rgba(99,102,241,0.25)'
                  : user?.role === 'teacher'
                  ? 'rgba(16,185,129,0.25)'
                  : 'rgba(245,158,11,0.25)'
              }`,
            }}
          >
            <p
              style={{
                fontSize: 12,
                fontWeight: 600,
                color: dark ? '#94a3b8' : '#64748b',
                marginBottom: 4,
              }}
            >
              Logged in as
            </p>
            <p
              style={{
                fontSize: 14,
                fontWeight: 700,
                color: dark ? '#f1f5f9' : '#0f0f23',
              }}
            >
              {user?.name}
            </p>
            <p
              style={{
                fontSize: 12,
                color:
                  user?.role === 'student'
                    ? '#818cf8'
                    : user?.role === 'teacher'
                    ? '#34d399'
                    : '#fbbf24',
                fontWeight: 600,
                textTransform: 'capitalize',
                marginTop: 2,
              }}
            >
              {user?.role} Account
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
